"use client";

import * as React from "react";
import styles from "../styles/scroll-timeline.module.css";

interface SmoothScrollState {
  /** Current scrollTop of the viewport in px */
  scroll: number;
  /** Maximum scrollTop in px */
  limit: number;
  /** scroll / limit, 0..1 */
  progress: number;
  /** Signed scroll velocity in px per 60fps frame */
  velocity: number;
}

interface SmoothScrollOptions {
  lerp: number;
  wheelMultiplier: number;
  smooth: boolean;
  onScroll?: (state: SmoothScrollState) => void;
}

const clamp = (v: number, min: number, max: number) => Math.min(max, Math.max(min, v));

function usePrefersReducedMotion(): boolean {
  const [reduced, setReduced] = React.useState(false);
  React.useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReduced(mq.matches);
    update();
    mq.addEventListener("change", update);
    return () => mq.removeEventListener("change", update);
  }, []);
  return reduced;
}

/** True when a nested scrollable element under the pointer can still scroll in the wheel direction. */
function nestedCanScroll(node: EventTarget | null, root: HTMLElement, dy: number): boolean {
  let el: Element | null = node instanceof Element ? node : null;
  while (el && el !== root) {
    if (el instanceof HTMLElement) {
      if (el.dataset.mfScrollPrevent !== undefined) return true;
      const overflowY = window.getComputedStyle(el).overflowY;
      if ((overflowY === "auto" || overflowY === "scroll") && el.scrollHeight > el.clientHeight + 1) {
        const canMove = dy < 0 ? el.scrollTop > 0 : el.scrollTop + el.clientHeight < el.scrollHeight - 1;
        if (canMove) return true;
      }
    }
    el = el.parentElement;
  }
  return false;
}

/**
 * Self-contained smooth scroller for an overflow container. Wheel input updates a target
 * position; a rAF loop eases the real scrollTop toward it (frame-rate independent lerp) and
 * stops once settled. Touch, keyboard and scrollbar drags stay native. At the top/bottom edge
 * wheel events are released so the page keeps scrolling.
 */
function useSmoothScroll(
  containerRef: React.RefObject<HTMLElement | null>,
  { lerp, wheelMultiplier, smooth, onScroll }: SmoothScrollOptions,
): React.RefObject<SmoothScrollState> {
  const stateRef = React.useRef<SmoothScrollState>({ scroll: 0, limit: 0, progress: 0, velocity: 0 });
  const callbackRef = React.useRef(onScroll);
  React.useEffect(() => {
    callbackRef.current = onScroll;
  }, [onScroll]);

  React.useEffect(() => {
    const el = containerRef.current;
    if (!el) return;
    const ease = clamp(Number.isFinite(lerp) ? lerp : 0.1, 0.01, 1);
    const multiplier = Number.isFinite(wheelMultiplier) ? wheelMultiplier : 1;
    let target = el.scrollTop;
    let current = target;
    let raf = 0;
    let lastTime = 0;
    let lastNative = el.scrollTop;
    let lastNativeTime = 0;
    let settleTimer: ReturnType<typeof setTimeout> | undefined;

    const getLimit = () => Math.max(0, el.scrollHeight - el.clientHeight);

    const emit = (velocity: number) => {
      const limit = getLimit();
      const scroll = clamp(el.scrollTop, 0, limit);
      lastNative = el.scrollTop;
      const s = stateRef.current;
      s.scroll = scroll;
      s.limit = limit;
      s.progress = limit > 0 ? scroll / limit : 0;
      s.velocity = velocity;
      callbackRef.current?.(s);
    };

    const tick = (time: number) => {
      const dt = lastTime ? Math.min(64, Math.max(1, time - lastTime)) : 16.667;
      lastTime = time;
      const limit = getLimit();
      target = clamp(target, 0, limit);
      if (Math.abs(el.scrollTop - current) > 2) {
        // Something else moved the viewport (scrollbar drag, keyboard, touch): hand control back.
        current = target = el.scrollTop;
        raf = 0;
        lastTime = 0;
        emit(0);
        return;
      }
      const prev = current;
      const frames = dt / 16.667;
      current += (target - current) * (1 - Math.pow(1 - ease, frames));
      if (Math.abs(target - current) < 0.35) current = target;
      el.scrollTop = current;
      emit((current - prev) / frames);
      if (current === target) {
        raf = 0;
        lastTime = 0;
        emit(0);
        return;
      }
      raf = requestAnimationFrame(tick);
    };

    const onWheel = (event: WheelEvent) => {
      if (event.ctrlKey || event.defaultPrevented) return;
      if (Math.abs(event.deltaX) > Math.abs(event.deltaY)) return;
      let dy = event.deltaY;
      if (event.deltaMode === 1) dy *= 16;
      else if (event.deltaMode === 2) dy *= el.clientHeight;
      dy *= multiplier;
      if (dy === 0 || nestedCanScroll(event.target, el, dy)) return;
      const limit = getLimit();
      if (!raf) current = target = el.scrollTop;
      // Release to native scrolling at the edges so the page is never trapped.
      if ((dy < 0 && target <= 0) || (dy > 0 && target >= limit - 0.5)) return;
      event.preventDefault();
      target = clamp(target + dy, 0, limit);
      if (!raf) {
        lastTime = 0;
        raf = requestAnimationFrame(tick);
      }
    };

    const onNativeScroll = () => {
      if (raf) return;
      const top = el.scrollTop;
      const delta = top - lastNative;
      if (delta === 0) return;
      const now = performance.now();
      const dt = lastNativeTime ? clamp(now - lastNativeTime, 8, 100) : 16.667;
      lastNativeTime = now;
      current = target = top;
      emit(delta / (dt / 16.667));
      if (settleTimer) clearTimeout(settleTimer);
      settleTimer = setTimeout(() => {
        lastNativeTime = 0;
        emit(0);
      }, 90);
    };

    if (smooth) el.addEventListener("wheel", onWheel, { passive: false });
    el.addEventListener("scroll", onNativeScroll, { passive: true });
    const ro = new ResizeObserver(() => emit(stateRef.current.velocity));
    ro.observe(el);
    if (el.firstElementChild) ro.observe(el.firstElementChild);
    emit(0);

    return () => {
      if (smooth) el.removeEventListener("wheel", onWheel);
      el.removeEventListener("scroll", onNativeScroll);
      ro.disconnect();
      if (raf) cancelAnimationFrame(raf);
      if (settleTimer) clearTimeout(settleTimer);
    };
  }, [containerRef, lerp, wheelMultiplier, smooth]);

  return stateRef;
}

export interface ScrollTimelineProps {
  /** Milestone titles, one per timeline entry */
  items?: string[];
  /** Optional description per milestone (matched by index) */
  descriptions?: string[];
  /** Heading shown above the timeline */
  title?: string;
  /** Accent color for the drawn line and active dots */
  accentColor?: string;
  /** Viewport height in px */
  height?: number;
  /** Viewport corner radius in px */
  borderRadius?: number;
  /** Interpolation factor per 60fps frame (0.05 = floaty, 0.3 = snappy) */
  lerp?: number;
  /** Multiplier applied to wheel / trackpad deltas */
  wheelMultiplier?: number;
  /** Enable smooth wheel scrolling (native scrolling when false or under reduced motion) */
  smooth?: boolean;
  /** Optional className merged onto the root */
  className?: string;
  /** Inline styles merged onto the root */
  style?: React.CSSProperties;
}

const DEFAULT_ITEMS = [
  "Idea on a napkin",
  "First prototype",
  "Private beta",
  "Public launch",
  "10k teams onboard",
  "What comes next",
];

const DEFAULT_DESCRIPTIONS = [
  "A late-night sketch of a motion library that stays out of the way.",
  "Twelve components, one rAF loop, zero dependencies beyond React.",
  "Forty studios stress-test every easing curve and edge case.",
  "Docs, playground and CLI ship the same afternoon.",
  "Teams across product, marketing and games build with it daily.",
  "Scroll-driven scenes, physics and a visual timeline editor.",
];

/** Fraction of the viewport height where the line tip sits. */
const ANCHOR = 0.6;

export function ScrollTimeline({
  items = DEFAULT_ITEMS,
  descriptions = DEFAULT_DESCRIPTIONS,
  title = "How we got here",
  accentColor = "#34d399",
  height = 380,
  borderRadius = 20,
  lerp = 0.1,
  wheelMultiplier = 1,
  smooth = true,
  className = "",
  style,
}: ScrollTimelineProps) {
  const reduced = usePrefersReducedMotion();
  const rootRef = React.useRef<HTMLDivElement>(null);
  const viewportRef = React.useRef<HTMLDivElement>(null);
  const listRef = React.useRef<HTMLDivElement>(null);
  const itemRefs = React.useRef<(HTMLLIElement | null)[]>([]);
  const geometryRef = React.useRef({ listTop: 0, listHeight: 1, dots: [] as number[] });
  const stateRef = React.useRef({ scroll: 0, progress: 0, viewport: 0 });
  const total = items.length;

  const apply = React.useCallback(() => {
    const root = rootRef.current;
    if (!root) return;
    const { listTop, listHeight, dots } = geometryRef.current;
    const { scroll, progress, viewport } = stateRef.current;
    const anchor = progress >= 0.999 ? Number.POSITIVE_INFINITY : scroll + viewport * ANCHOR - listTop;
    const fill = clamp(anchor / listHeight, 0, 1);
    root.style.setProperty("--mf-st-fill", fill.toFixed(4));
    for (let i = 0; i < total; i++) {
      const item = itemRefs.current[i];
      if (!item) continue;
      const active = anchor >= (dots[i] ?? 0);
      if ((item.dataset.active === "true") !== active) item.dataset.active = active ? "true" : "false";
    }
  }, [total]);

  const handleScroll = React.useCallback(
    (state: SmoothScrollState) => {
      stateRef.current.scroll = state.scroll;
      stateRef.current.progress = state.progress;
      apply();
    },
    [apply],
  );

  useSmoothScroll(viewportRef, { lerp, wheelMultiplier, smooth: smooth && !reduced, onScroll: handleScroll });

  React.useEffect(() => {
    const list = listRef.current;
    const viewport = viewportRef.current;
    if (!list || !viewport) return;
    const measure = () => {
      geometryRef.current = {
        listTop: list.offsetTop,
        listHeight: Math.max(1, list.offsetHeight),
        dots: itemRefs.current.slice(0, total).map((node) => (node ? node.offsetTop + 22 : 0)),
      };
      stateRef.current.viewport = viewport.clientHeight;
      apply();
    };
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(list);
    ro.observe(viewport);
    return () => ro.disconnect();
  }, [total, apply]);

  const vars = {
    "--mf-st-h": `${height}px`,
    "--mf-st-r": `${borderRadius}px`,
    "--mf-st-accent": accentColor,
    ...style,
  } as React.CSSProperties;

  return (
    <div ref={rootRef} style={vars} className={`${styles.root} ${className}`.trim()}>
      <div ref={viewportRef} className={styles.viewport} tabIndex={0} role="region" aria-label={title}>
        <div className={styles.content}>
          <header className={styles.header}>
            <span className={styles.kicker}>Timeline</span>
            <h3 className={styles.title}>{title}</h3>
          </header>
          <div ref={listRef} className={styles.timeline}>
            <span aria-hidden="true" className={styles.line}>
              <span className={styles.lineFill} />
            </span>
            <ol className={styles.list}>
              {items.map((item, i) => (
                <li
                  key={`${item}-${i}`}
                  ref={(node) => {
                    itemRefs.current[i] = node;
                  }}
                  className={styles.item}
                >
                  <span aria-hidden="true" className={styles.dot} />
                  <div className={styles.card}>
                    <span className={styles.step}>{`Milestone ${String(i + 1).padStart(2, "0")}`}</span>
                    <span className={styles.itemTitle}>{item}</span>
                    {descriptions[i] && <p className={styles.description}>{descriptions[i]}</p>}
                  </div>
                </li>
              ))}
            </ol>
          </div>
        </div>
      </div>
    </div>
  );
}

.root {
  --mf-st-fill: 0;
  position: relative;
  width: 100%;
  height: var(--mf-st-h, 380px);
  border-radius: var(--mf-st-r, 20px);
  overflow: hidden;
  border: 1px solid var(--mf-border, #2e2e38);
  background: var(--mf-surface, #141419);
  color: var(--mf-fg, #f4f4f6);
  container-type: inline-size;
  isolation: isolate;
}

.root *,
.root *::before,
.root *::after {
  box-sizing: border-box;
}

.viewport {
  position: relative;
  height: 100%;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: auto;
  scroll-behavior: auto;
  scrollbar-width: thin;
  scrollbar-color: var(--mf-border, #2e2e38) transparent;
}

.viewport:focus-visible {
  outline: 2px solid var(--mf-fg, #e4e4e7);
  outline-offset: -2px;
}

.content {
  position: relative;
  max-width: 40rem;
  margin: 0 auto;
  padding: 0 clamp(1.25rem, 6cqi, 2.5rem) calc(var(--mf-st-h, 380px) * 0.45);
}

.header {
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  gap: 0.55rem;
  min-height: calc(var(--mf-st-h, 380px) * 0.5);
  padding-bottom: 2rem;
}

.kicker {
  align-self: flex-start;
  padding: 0.3rem 0.75rem;
  border: 1px solid var(--mf-border, #2e2e38);
  border-radius: 999px;
  font-size: 0.72rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--mf-st-accent, #34d399);
}

.title {
  margin: 0;
  font-size: clamp(1.8rem, 6cqi, 2.8rem);
  font-weight: 700;
  line-height: 1.05;
  letter-spacing: -0.035em;
}

.timeline {
  position: relative;
}

.line {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 15px;
  width: 2px;
  border-radius: 2px;
  background: var(--mf-border, #2e2e38);
  overflow: hidden;
}

.lineFill {
  display: block;
  width: 100%;
  height: 100%;
  background: linear-gradient(180deg, color-mix(in srgb, var(--mf-st-accent, #34d399) 30%, transparent), var(--mf-st-accent, #34d399));
  transform: scaleY(var(--mf-st-fill, 0));
  transform-origin: 50% 0%;
  will-change: transform;
}

.list {
  margin: 0;
  padding: 0;
  list-style: none;
}

.item {
  position: relative;
  padding: 0 0 2.25rem 3rem;
}

.item:last-child {
  padding-bottom: 0;
}

.dot {
  position: absolute;
  left: 9px;
  top: 15px;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  border: 2px solid var(--mf-border-strong, #3f3f4a);
  background: var(--mf-surface, #141419);
  transition:
    transform 420ms cubic-bezier(0.34, 1.56, 0.64, 1),
    background-color 300ms ease,
    border-color 300ms ease,
    box-shadow 300ms ease;
}

.card {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  padding: 0.9rem 1.1rem;
  border: 1px solid var(--mf-border, #2e2e38);
  border-radius: 14px;
  background: var(--mf-surface-raised, #1b1b22);
  opacity: 0.25;
  transform: translateX(28px);
  transition:
    opacity 500ms ease,
    transform 600ms cubic-bezier(0.16, 1, 0.3, 1),
    border-color 500ms ease;
}

.step {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 0.7rem;
  letter-spacing: 0.04em;
  color: var(--mf-muted, #a1a1aa);
}

.itemTitle {
  font-size: 1.1rem;
  font-weight: 600;
  letter-spacing: -0.02em;
}

.description {
  margin: 0;
  color: var(--mf-muted, #a1a1aa);
  font-size: 0.86rem;
  line-height: 1.55;
}

.item[data-active="true"] .dot {
  transform: scale(1.3);
  border-color: var(--mf-st-accent, #34d399);
  background: var(--mf-st-accent, #34d399);
  box-shadow: 0 0 0 5px color-mix(in srgb, var(--mf-st-accent, #34d399) 20%, transparent), 0 0 18px var(--mf-st-accent, #34d399);
}

.item[data-active="true"] .card {
  opacity: 1;
  transform: none;
  border-color: color-mix(in srgb, var(--mf-st-accent, #34d399) 40%, var(--mf-border, #2e2e38));
}

.item[data-active="true"] .step {
  color: var(--mf-st-accent, #34d399);
}

@media (prefers-reduced-motion: reduce) {
  .dot,
  .card {
    transition: none;
  }

  .card {
    transform: none;
  }

  .item[data-active="true"] .dot {
    transform: none;
  }

  .lineFill {
    will-change: auto;
  }
}

