"use client";

import { useEffect, useRef } from "react";

function useSmooth(ref, onFrame, lerp = 0.1) {
  useEffect(() => {
    const el = ref.current;
    let target = el.scrollTop, raf = 0;
    const emit = () => { const max = el.scrollHeight - el.clientHeight; onFrame(el.scrollTop, max > 0 ? el.scrollTop / max : 0); };
    const tick = () => {
      const d = target - el.scrollTop;
      el.scrollTop += Math.abs(d) < 0.5 ? d : d * lerp;
      emit();
      raf = Math.abs(target - el.scrollTop) < 0.5 ? 0 : requestAnimationFrame(tick);
    };
    const onWheel = (e) => {
      const max = el.scrollHeight - el.clientHeight;
      if (!raf) target = el.scrollTop;
      if ((e.deltaY < 0 && target <= 0) || (e.deltaY > 0 && target >= max)) return;
      e.preventDefault();
      target = Math.min(max, Math.max(0, target + e.deltaY));
      if (!raf) raf = requestAnimationFrame(tick);
    };
    el.addEventListener("wheel", onWheel, { passive: false });
    el.addEventListener("scroll", () => { if (!raf) emit(); }, { passive: true });
    return () => { el.removeEventListener("wheel", onWheel); cancelAnimationFrame(raf); };
  }, []);
}

export function ScrollTimelineTailwind() {
  const ref = useRef(null);
  const fill = useRef(null);
  const dots = useRef([]);
  const items = ["Idea on a napkin", "First prototype", "Private beta", "Public launch", "10k teams onboard"];
  useSmooth(ref, (_, p) => {
    fill.current.style.transform = `scaleY(${p})`;
    dots.current.forEach((d, i) => d.classList.toggle("is-on", p >= i / (items.length - 1) - 0.02));
  });
  return (
    <div className="relative h-[380px] w-full overflow-hidden rounded-[20px] border border-zinc-800 bg-zinc-900 text-zinc-100">
      <div ref={ref} tabIndex={0} className="h-full overflow-y-auto px-10 py-[150px]">
        <div className="relative">
          <span className="absolute inset-y-0 left-[15px] w-0.5 bg-zinc-800"><span ref={fill} className="block h-full origin-top scale-y-0 bg-emerald-400" /></span>
          <ol>
            {items.map((t, i) => (
              <li key={t} ref={(n) => (dots.current[i] = n)} className="group relative pb-10 pl-12 opacity-30 transition-opacity duration-500 [&.is-on]:opacity-100">
                <span className="absolute left-[9px] top-1.5 h-3.5 w-3.5 rounded-full border-2 border-zinc-600 bg-zinc-900 transition group-[.is-on]:scale-125 group-[.is-on]:border-emerald-400 group-[.is-on]:bg-emerald-400" />
                <p className="text-lg font-semibold">{t}</p>
              </li>
            ))}
          </ol>
        </div>
      </div>
    </div>
  );
}
